// Exact p54 primitive q8 phase-specific affine inversion. Independent word starts
// and odd strides; all three-anchor lexical joins; up to three OOV words.
#include <bits/stdc++.h>
#include <codecvt>
#include <locale>
using namespace std;
using u64=uint64_t;using A=array<int,29>;using K=array<int,8>;
const string sym="0123456789abcdefghijklmnopqrs";
const u32string runes=U"ᚠᚢᚦᚩᚱᚳᚷᚹᚻᚾᛁᛄᛇᛈᛉᛋᛏᛒᛖᛗᛚᛝᛟᛞᚪᚫᚣᛡᛠ";
const vector<string> names={"F","U","TH","O","R","C","G","W","H","N","I","J","EO","P","X","S","T","B","E","M","L","NG","OE","D","A","AE","Y","IA","EA"};
int md(int x){return (x%29+29)%29;}
string file(const string&p){ifstream f(p);if(!f)throw runtime_error(p);return string(istreambuf_iterator<char>(f),{});}
vector<string> words(const string&s){istringstream f(s);vector<string> v;string w;while(f>>w)v.push_back(w);return v;}
vector<string> fields(const string&s,const string&k){regex re("\""+k+"\"\\s*:\\s*\"([^\"]*)\"");vector<string> v;for(sregex_iterator i(s.begin(),s.end(),re),e;i!=e;++i)v.push_back((*i)[1]);return v;}
set<string> D;vector<string> by[64],nof[64];unordered_set<string> lookup;
void spell(const string&s,int i,string w){if(i==(int)s.size()){D.insert(w);return;}for(int n=1;n<=3&&i+n<=(int)s.size();n++){auto t=s.substr(i,n);int j=-1;if(n==3){if(t=="ING")j=21;}else for(int x=0;x<29;x++)if(t==names[x]){j=x;break;}if(j>=0)spell(s,i+n,w+sym[j]);}}
void dictionary(){istringstream f(file("resources/control/english_wordfreq_textblob.txt"));string l;regex re("^([a-z]+)\\s+([0-9]+)$");smatch m;while(getline(f,l)){if(!regex_match(l,m,re))continue;string s=m[1],v,z;for(char c:s)v+=toupper(c);for(int i=0;i<(int)v.size();i++){if(v.substr(i,2)=="QU"){z+="CW";i++;continue;}char c=v[i];z+=c=='V'?'U':c=='K'||c=='Q'?'C':c=='Z'?'S':c;}spell(z,0,"");}if(D.size()!=38910)throw runtime_error("dictionary base");for(auto&w:words(fields(file("im-results/lp2-shared-gp29-q8-terminal-corrected-fixtures.json"),"added").at(0)))D.insert(w);if(D.size()!=38938)throw runtime_error("dictionary expanded");for(auto&w:D){lookup.insert(w);if(w.size()<64){by[w.size()].push_back(w);if(w.find('0')==string::npos)nof[w.size()].push_back(w);}}}
vector<string> runeGroups(const string&s){wstring_convert<codecvt_utf8<char32_t>,char32_t> cv;auto u=cv.from_bytes(s);vector<string> v;string w;for(auto c:u){size_t i=runes.find(c);if(i!=u32string::npos)w+=sym[i];else if(!w.empty()){v.push_back(w);w.clear();}}if(!w.empty())v.push_back(w);return v;}
vector<string> chapter(){auto s=file("resources/transcriptions/lp2-image-corrected.txt");wstring_convert<codecvt_utf8<char32_t>,char32_t> cv;auto u=cv.from_bytes(s);int pg=0;vector<string> v;string w;for(auto c:u){if(c==U'%'){pg++;continue;}if(pg<40||pg>=53)continue;if(c==U'/'||c==U'\n'||c==U'\r'||c==U' '||c==U'\t')continue;size_t i=runes.find(c);if(i!=u32string::npos)w+=sym[i];else if(!w.empty()){v.push_back(w);w.clear();}}if(!w.empty())v.push_back(w);int n=0;for(auto&x:v)n+=x.size();if(v.size()!=669||n!=3008)throw runtime_error("chapter shape");return v;}

// Exact phase-specific affine map recovery under source-selected q8,
// independent word phases and literal F. Ciphertext-only anchor coverage
// proves a qualifying pair despite <=6 OOV; <=1 unresolved phase.
constexpr int Q=8,MAPS=812;int mul[MAPS],add[MAPS],iv[MAPS],inverse[29],decodeMap[MAPS][29];
int mapid(int a,int b){if(a<=0||a>=29||b<0||b>=29)throw runtime_error("map");return (a-1)*29+b;}
int solve(int p,int c,int p2,int c2){int a=md(c2-c)*inverse[md(p2-p)]%29;if(!a)throw runtime_error("noninvertible pair");return mapid(a,md(c-a*p));}
void maps(){for(int x=1;x<29;x++)for(int y=1;y<29;y++)if(x*y%29==1)inverse[x]=y;for(int m=0;m<MAPS;m++){mul[m]=m/29+1;add[m]=m%29;iv[m]=inverse[mul[m]];for(int c=0;c<29;c++)decodeMap[m][c]=md(c-add[m])*iv[m]%29;}}
int forward(int m,int p){return (mul[m]*p+add[m])%29;}
string encrypt(const string&w,const K&k,int j,int stride){string c;for(char x:w){int p=sym.find(x);if(!p)c+='0';else{c+=sym[forward(k[j],p)];j=(j+stride)%Q;}}return c;}
bool support(const string&c,const K&k,const string*truth=nullptr){string w(c.size(),'0');for(int stride:{1,3,5,7}){function<bool(int,int)> rec=[&](int i,int j){if(i==(int)c.size())return truth?w==*truth:lookup.count(w)>0;int x=sym.find(c[i]);if(!x){w[i]='0';if(rec(i+1,j))return true;}int p=decodeMap[k[j]][x];if(!p)return false;w[i]=sym[p];return rec(i+1,(j+stride)%Q);};for(int j=0;j<Q;j++)if(rec(0,j))return true;}return false;}
K norm(K k){K b=k;for(int stride:{1,3,5,7})for(int j=0;j<Q;j++){K x;for(int h=0;h<Q;h++)x[h]=k[(j+stride*h)%Q];b=min(b,x);}return b;}
bool primitive(const K&k){for(int i=0;i<4;i++)if(k[i]!=k[i+4])return true;return false;}

// Terminal has six F-free >=8 anchors; <=3 OOV guarantees an inlier triple.
// Traverse three rephased lexical tries simultaneously using the exact
// coordinate-wise affine relation. This avoids a dictionary pair Cartesian
// product at every phase alignment. Every complete compatible triple is
// extended to all affine maps and validated on the corrected 47-word body.
struct Opt{string w;array<int,13> p{};};
struct Node{array<int,29> next;uint32_t mask=0;vector<int> leaf;Node(){next.fill(-1);}};
struct Trie{vector<Node> n{1};void add(const array<int,13>&p,int phase,int stride,int id){int a=0;for(int h=0;h<Q;h++){int x=p[((h-phase+Q)*stride)%Q];if(n[a].next[x]<0){n[a].next[x]=n.size();n[a].mask|=1u<<x;n.emplace_back();}a=n[a].next[x];}n[a].leaf.push_back(id);}};
struct Group{string c;vector<int> cv;vector<Opt> opts;array<Trie,4*Q> t;};
Group group(const string&c){Group g;g.c=c;for(char x:c)g.cv.push_back(sym.find(x));for(auto&w:nof[c.size()]){Opt o;o.w=w;bool ok=true;for(int j=0;j<(int)w.size();j++){o.p[j]=sym.find(w[j]);if(j>=Q&&(o.p[j]==o.p[j-Q])!=(c[j]==c[j-Q]))ok=false;}if(!ok)continue;int i=g.opts.size();g.opts.push_back(o);for(int st=0;st<4;st++)for(int ph=0;ph<Q;ph++)g.t[st*Q+ph].add(o.p,ph,2*st+1,i);}return g;}
struct KH{size_t operator()(const K&k)const{uint64_t h=0x123456789abcdefULL;for(auto x:k)h=(h^(x+0x9e3779b97f4a7c15ULL))*0xbf58476d1ce4e5b9ULL;return h^(h>>31);}};
template<class T>string ar(const T&v){string s="[";for(auto x:v){if(s.size()>1)s+=",";s+=to_string(+x);}return s+"]";}
struct Fit{K key;int training;};struct Stat{uint64_t alignments=0,nodes=0,childPairs=0,leafTriples=0,consistent=0,keys=0,dups=0;int maxMissing=0;vector<Fit> fits;};
struct Relation{int a,b,c;bool all;array<array<uint8_t,29>,29> t{};};
Stat recover(const vector<string>&C,const vector<int>&ids){vector<Group> g;for(int i:ids)g.push_back(group(C[i]));Stat s;unordered_set<K,KH> seen;seen.reserve(100000);
auto validate=[&](K k){if(!primitive(k))return;k=norm(k);if(!seen.insert(k).second){s.dups++;return;}s.keys++;int tr=0,bad=0;for(auto&c:C){if(support(c,k))tr++;else if(++bad>3)return;}if(tr>=int(C.size())-3)s.fits.push_back({k,tr});};
for(int i=0;i<6;i++)for(int j=i+1;j<6;j++)for(int k=j+1;k<6;k++)for(int d=0;d<4*Q;d++)for(int e=0;e<4*Q;e++){
s.alignments++;array<int,3> idx{i,j,k},ph{0,d%Q,e%Q},st{1,2*(d/Q)+1,2*(e/Q)+1};array<const Group*,3> gs{&g[i],&g[j],&g[k]};array<const Trie*,3> ts{&g[i].t[0],&g[j].t[d],&g[k].t[e]};array<Relation,Q> rel{};
for(int h=0;h<Q;h++){array<int,3> c{};for(int a=0;a<3;a++)c[a]=gs[a]->cv[((h-ph[a]+Q)*st[a])%Q];auto&r=rel[h];r.all=c[0]==c[1]&&c[1]==c[2];if(r.all)continue;r.a=0;r.b=c[0]!=c[1]?1:2;r.c=3-r.a-r.b;int ratio=md(c[r.c]-c[r.a])*inverse[md(c[r.b]-c[r.a])]%29;for(int p=1;p<29;p++)for(int q=1;q<29;q++)if(p!=q)r.t[p][q]=md(p+ratio*(q-p));}
auto leaf=[&](const array<int,3>&v){for(int a:ts[0]->n[v[0]].leaf)for(int b:ts[1]->n[v[1]].leaf)for(int c:ts[2]->n[v[2]].leaf){s.leafTriples++;array<const Opt*,3> os{&gs[0]->opts[a],&gs[1]->opts[b],&gs[2]->opts[c]};K key;key.fill(-1);array<int,Q> p0{},c0{};vector<int> miss;bool ok=true;for(int h=0;h<Q&&ok;h++){bool first=true;int p=-1,x=-1,m=-1;for(int z=0;z<3&&ok;z++){int l=((h-ph[z]+Q)*st[z])%Q;for(int t=l;t<(int)gs[z]->c.size();t+=Q){int q=os[z]->p[t],y=gs[z]->cv[t];if(first){p=q;x=y;first=false;}else if(m>=0){if(forward(m,q)!=y)ok=false;}else if(p==q){if(x!=y)ok=false;}else if(x==y)ok=false;else m=solve(p,x,q,y);if(!ok)break;}}if(m<0){p0[h]=p;c0[h]=x;miss.push_back(h);}else key[h]=m;}if(!ok)continue;s.consistent++;s.maxMissing=max(s.maxMissing,(int)miss.size());function<void(int)> fill=[&](int z){if(z==(int)miss.size()){validate(key);return;}int h=miss[z];for(int a=1;a<29;a++){key[h]=mapid(a,md(c0[h]-a*p0[h]));fill(z+1);}};fill(0);}};
function<void(int,array<int,3>)> dfs=[&](int h,array<int,3> v){s.nodes++;if(h==Q){leaf(v);return;}array<const Node*,3> n{&ts[0]->n[v[0]],&ts[1]->n[v[1]],&ts[2]->n[v[2]]};auto&r=rel[h];if(r.all){uint32_t mask=n[0]->mask&n[1]->mask&n[2]->mask;while(mask){int p=__builtin_ctz(mask);mask&=mask-1;dfs(h+1,{n[0]->next[p],n[1]->next[p],n[2]->next[p]});}return;}uint32_t pa=n[r.a]->mask;while(pa){int p=__builtin_ctz(pa);pa&=pa-1;uint32_t qb=n[r.b]->mask&~(1u<<p);while(qb){int q=__builtin_ctz(qb);qb&=qb-1;s.childPairs++;int t=r.t[p][q];if(!t||!(n[r.c]->mask&(1u<<t)))continue;array<int,3> next;next[r.a]=n[r.a]->next[p];next[r.b]=n[r.b]->next[q];next[r.c]=n[r.c]->next[t];dfs(h+1,next);}}};dfs(0,{0,0,0});
}return s;}
vector<string> arrfield(const string&s,const string&k){regex re("\""+k+"\"\\s*:\\s*\\[([^\\]]*)\\]");smatch m;if(!regex_search(s,m,re))throw runtime_error(k);string t=m[1];regex z("\"([0-9a-s]+)\"");vector<string>v;for(sregex_iterator i(t.begin(),t.end(),z),e;i!=e;++i)v.push_back((*i)[1]);return v;}
int main(int argc,char**argv){dictionary();maps();string mode=argc>1?argv[1]:"0";bool control=mode!="original";auto f=file("resources/liber-primus/lp2-page-groups-54-55-derived.json");auto C=arrfield(f,"body_groups"),H=arrfield(f,"groups");H[0]=C.back()+H[0];C.pop_back();if(C.size()!=47||H.size()!=17)throw runtime_error("profile");vector<int>ids;for(int j=0;j<47;j++)if(C[j].size()>=8&&C[j].find('0')==string::npos)ids.push_back(j);if(ids.size()!=6)throw runtime_error("anchors");vector<string>T,HT;K key{};vector<int>omit;
if(control){int i=stoi(mode);auto t=words(fields(file("im-results/lp2-shared-gp29-q8-terminal-corrected-fixtures.json"),"truth").at(i));T.assign(t.begin(),t.begin()+47);mt19937 rng(0x8af52920u+i);HT.push_back(by[11][rng()%by[11].size()]);HT.insert(HT.end(),t.begin()+49,t.end());for(auto&x:key)x=rng()%MAPS;if(!primitive(key))key[7]=(key[7]+1)%MAPS;auto v=ids;shuffle(v.begin(),v.end(),rng);omit.assign(v.begin(),v.begin()+3);sort(omit.begin(),omit.end());for(int j=0;j<47;j++){bool ff=find(ids.begin(),ids.end(),j)!=ids.end(),bad=find(omit.begin(),omit.end(),j)!=omit.end();int n=C[j].size();string orig=T[j];for(int tries=0;;tries++){if(tries>100000)throw runtime_error("plant retries");if(bad){T[j].clear();for(int x=0;x<n;x++)T[j]+=sym[1+rng()%28];}else if(tries||!lookup.count(orig)||(ff&&orig.find('0')!=string::npos)){auto&v=ff?nof[n]:by[n];T[j]=v[rng()%v.size()];}C[j]=encrypt(T[j],key,rng()%Q,2*(rng()%4)+1);if(ff&&C[j].find('0')!=string::npos)continue;if(bad&&support(C[j],key))continue;break;}}for(int j=0;j<17;j++)H[j]=encrypt(HT[j],key,rng()%Q,2*(rng()%4)+1);}
auto R=recover(C,ids);ostringstream o;o<<"{\"mode\":\""<<mode<<"\",\"dictionary\":"<<D.size()<<",\"budget\":3,\"anchor_ids\":"<<ar(ids)<<",\"alignments\":"<<R.alignments<<",\"nodes\":"<<R.nodes<<",\"child_pairs\":"<<R.childPairs<<",\"leaf_triples\":"<<R.leafTriples<<",\"consistent\":"<<R.consistent<<",\"max_missing\":"<<R.maxMissing<<",\"keys\":"<<R.keys<<",\"duplicates\":"<<R.dups<<",\"fit_count\":"<<R.fits.size()<<",\"omitted\":"<<ar(omit)<<",\"fits\":[";int exact=0,ht=0,tr=0;for(int i=0;i<(int)R.fits.size();i++){auto&x=R.fits[i];if(control&&x.key==norm(key)){exact++;for(int j=0;j<47;j++)tr+=support(C[j],x.key,&T[j]);for(int j=0;j<17;j++)ht+=support(H[j],x.key,&HT[j]);}if(i>=20)continue;int held=0;for(auto&w:H)held+=support(w,x.key);if(i)o<<",";o<<"{\"key\":"<<ar(x.key)<<",\"training\":"<<x.training<<",\"held\":"<<held<<"}";}o<<"],\"exact\":"<<exact<<",\"train_truth\":"<<tr<<",\"held_truth\":"<<ht<<",\"held_count\":"<<H.size()<<"}";cout<<"FINAL "<<o.str()<<endl;if(const char*p=getenv("SFT_OUTPUT")){ofstream f(p);f<<o.str()<<endl;}return 0;}
